        "code": "import requests
import json

def main(url: str):
    # Parse GitHub URL
    owner = url.split('/')[3]
    repo = url.split('/')[4]

    # Fetch README content
    readme_api = f'https://api.github.com/repos/{owner}/{repo}/readme'
    headers = {'Accept': 'application/vnd.github.v3+json'}
    readme_response = requests.get(readme_api, headers=headers)
    readme_content = readme_response.json().get('content', '')
    readme_text = bytes.decode(base64.b64decode(readme_content), 'utf-8') if readme_content else 'README not found'

    # Fetch file structure
    def fetch_contents(path='')):
        api_url = f'https://api.github.com/repos/{owner}/{repo}/contents/{path}'
        response = requests.get(api_url, headers=headers)
        return response.json() if response.status_code == 200 else []

    def format_tree(structure, prefix=""):
        result = ""
        for item in structure:
            result += f"{prefix}├── {item['name']}\n"
            if 'contents' in item:
                result += format_tree(item['contents'], prefix + "    ")
        return result

    # Analyze file structure for technologies
    def analyze_technologies(files):
        lang_counts = {}
        for file in files:
            if file['type'] == 'file':
                ext = file['name'].split('.')[-1].lower()
                lang_counts[ext] = lang_counts.get(ext, 0) + 1
        return lang_counts

    # Build file tree
    root_files = fetch_contents()
    file_tree = format_tree(root_files)

    # Analyze technologies
    tech_analysis = analyze_technologies(root_files)

    # Generate Markdown summary
    summary = "# GitHub Project Summary\n\n## Project Overview\n" + readme_text + "\n\n## Key Technologies\n" + "\n".join([f"- {lang}: {count} files" for lang, count in tech_analysis.items()]) + "\n\n## File Structure\n" + file_tree
    return {'summary': summary}"
